const dashboardList = `-- name: DashboardList :many
SELECT
  d.id,
  d.agent_name,
  d.name,
  d.title,
  d.created_at,
  count(w.revision)::integer AS widget_count
FROM dashboards d
LEFT JOIN dashboard_widgets w
  ON w.dashboard_id = d.id
 AND w.tenant_namespace = d.tenant_namespace
WHERE d.tenant_namespace = $1
  AND d.workspace_id = $2
  AND (
    $3::text IS NULL OR
    d.agent_name = $3::text
  )
  AND (
    cardinality($4::text[]) = 0 OR
    d.agent_name = ANY($4::text[])
  )
  AND (
    $5::timestamptz IS NULL OR
    (d.created_at, d.id) < (
      $5::timestamptz,
      $6::uuid
    )
  )
GROUP BY d.id
ORDER BY d.created_at DESC, d.id DESC
LIMIT $7
`

