const dashboardReserveLatestUsage = `-- name: DashboardReserveLatestUsage :one
INSERT INTO dashboard_agent_usage (tenant_namespace, agent_name, latest_bytes)
SELECT
  $1 AS tenant_namespace,
  $2 AS agent_name,
  greatest($3, 0)::bigint AS latest_bytes
WHERE $3 <= $4
ON CONFLICT (tenant_namespace, agent_name)
DO UPDATE SET
  latest_bytes = dashboard_agent_usage.latest_bytes + $3,
  updated_at = now()
WHERE dashboard_agent_usage.latest_bytes + $3 BETWEEN 0 AND $4
RETURNING latest_bytes
`

